/**
 * NOVIDADE - aviso de pacote em aberto na finalizacao do atendimento
 *
 * O PROBLEMA QUE ISSO RESOLVE
 *
 * Com o controle de pacotes, o dinheiro adiantado fica registrado - mas
 * so quem criou o pacote sabe que ele existe. Quando a cliente chega para
 * a sessao, quem finaliza o atendimento nao tem como saber que ela ja
 * pagou. O risco e cobrar de novo, contando a mesma quantia duas vezes no
 * faturamento.
 *
 * Consultar a ficha antes de cada atendimento resolveria, mas depende de
 * alguem lembrar - e o esquecimento custa dinheiro toda vez.
 *
 * A NOVIDADE
 *
 * Na tela de finalizar atendimento, se a cliente tiver pacote em aberto,
 * aparece um aviso destacado em amarelo, logo acima do campo de valor,
 * mostrando:
 *
 *   - o nome do pacote;
 *   - quanto ela ja pagou e de quanto e o total;
 *   - quanto ainda falta;
 *   - um botao "Zerar valor (faz parte do pacote)", que coloca o valor do
 *     servico em R$ 0,00 com um clique.
 *
 * Quando o valor ja esta zerado, o aviso confirma que nada sera cobrado
 * naquela sessao.
 *
 * A informacao chega sozinha na hora em que importa - ninguem precisa
 * lembrar de consultar nada antes.
 *
 * DETALHE: o aviso nao aparece em retornos (que ja sao sem cobranca por
 * natureza) e some sozinho quando o pacote e quitado.
 *
 * Como usar: coloque este arquivo na RAIZ do projeto e rode
 *     node avisar-pacote-na-finalizacao.mjs
 *
 * PRE-REQUISITO: o script adicionar-saldo-de-pacote.mjs precisa ja ter
 * sido aplicado (e o que cria os pacotes).
 *
 * E seguro rodar duas vezes.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { Buffer } from "node:buffer";

console.log("\nNovidade - aviso de pacote na finalizacao\n");

if (!existsSync("package.json")) {
  console.error("ERRO: rode este script na pasta raiz do projeto (a mesma do package.json).\n");
  process.exit(1);
}

if (!existsSync("actions/pacote.actions.ts")) {
  console.error("ERRO: o controle de pacotes ainda nao foi instalado.\n");
  console.error("Rode antes:  node adicionar-saldo-de-pacote.mjs\n");
  process.exit(1);
}

